// ── Complexity class demonstrations ─────────────────────────────

// O(1) — constant regardless of input size
function getFirst(arr) { return arr[0]; }
function hashLookup(map, key) { return map.get(key); }

// O(log n) — binary search, input halves every iteration
function binarySearch(arr, target) {
  let lo = 0, hi = arr.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;       // >> 1 is integer divide by 2
    if (arr[mid] === target) return mid;
    if (arr[mid] < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}
// For arr of length 1,000,000,000: at most ~30 iterations
console.log(binarySearch([1, 3, 5, 7, 9, 11, 13], 7)); // 3

// O(n) — single pass
function prefixSums(arr) {
  const out = Array(arr.length);
  out[0] = arr[0];
  for (let i = 1; i < arr.length; i++) out[i] = out[i-1] + arr[i];
  return out;
}

// O(n log n) — merge sort (recurrence: T(n) = 2T(n/2) + O(n))
function mergeSort(arr) {
  if (arr.length <= 1) return arr;
  const mid = arr.length >> 1;
  const L = mergeSort(arr.slice(0, mid));
  const R = mergeSort(arr.slice(mid));
  const out = []; let i = 0, j = 0;
  while (i < L.length && j < R.length)
    out.push(L[i] <= R[j] ? L[i++] : R[j++]);
  return out.concat(L.slice(i)).concat(R.slice(j));
}
console.log(mergeSort([5, 2, 8, 1, 9, 3])); // [1,2,3,5,8,9]

// O(n²) — all unique pairs (nested loops)
function countPairs(arr) {
  let count = 0;
  for (let i = 0; i < arr.length; i++)
    for (let j = i + 1; j < arr.length; j++)
      count++;
  return count; // = n*(n-1)/2
}
console.log(countPairs([1,2,3,4])); // 6 pairs = 4*3/2

// O(2^n) — naive Fibonacci (avoid for n > 40)
function fibNaive(n) { return n <= 1 ? n : fibNaive(n-1) + fibNaive(n-2); }

// O(n) memoised — same results, vastly different cost
function fibMemo(n, cache = new Map()) {
  if (n <= 1) return n;
  if (cache.has(n)) return cache.get(n);
  const result = fibMemo(n-1, cache) + fibMemo(n-2, cache);
  cache.set(n, result);
  return result;
}
console.log(fibMemo(50)); // 12586269025, instant

