// ── Space complexity patterns ─────────────────────────────────

// O(1) space — in-place two-pointer reverse (no extra array)
function reverseInPlace(arr) {
  let l = 0, r = arr.length - 1;
  while (l < r) {
    [arr[l], arr[r]] = [arr[r], arr[l]];
    l++; r--;
  }
  return arr;
}
console.log(reverseInPlace([1,2,3,4,5])); // [5,4,3,2,1]

// O(n) space — creates a new reversed array
function reverseNew(arr) { return [...arr].reverse(); }

// O(n) call stack — linear recursion (n frames deep before unwinding)
function sumRecursive(arr, i = 0) {
  if (i === arr.length) return 0;
  return arr[i] + sumRecursive(arr, i + 1); // n frames on the stack!
}
// For large arrays this causes: RangeError: Maximum call stack size exceeded

// O(log n) call stack — divide and conquer
function sumDivide(arr, lo = 0, hi = arr.length - 1) {
  if (lo === hi) return arr[lo];
  const mid = (lo + hi) >> 1;
  return sumDivide(arr, lo, mid) + sumDivide(arr, mid + 1, hi);
  // Maximum stack depth = log2(n) — safe for huge arrays
}

// ── Classic time-space trade-off ─────────────────────────────
// Duplicate check: O(n²) time, O(1) space
function hasDupSlow(arr) {
  for (let i = 0; i < arr.length; i++)
    for (let j = i+1; j < arr.length; j++)
      if (arr[i] === arr[j]) return true;
  return false;
}

// Duplicate check: O(n) time, O(n) space — pay memory for speed
function hasDupFast(arr) {
  const seen = new Set();
  for (const x of arr) {
    if (seen.has(x)) return true;
    seen.add(x);
  }
  return false;
}
console.log(hasDupFast([3, 1, 4, 1, 5])); // true — 1 appears twice

// Two Sum: O(n) time, O(n) space with hash map
function twoSum(nums, target) {
  const seen = new Map(); // value → index
  for (let i = 0; i < nums.length; i++) {
    const complement = target - nums[i];
    if (seen.has(complement)) return [seen.get(complement), i];
    seen.set(nums[i], i);
  }
  return [];
}
console.log(twoSum([2, 7, 11, 15], 9)); // [0, 1]
